INSERT INTO faqs(intent,question,answer,language) VALUES('bus_routes','How can I find a bus route?','Use the route information section or contact the authority if the required route is not listed. / අවශ්‍ය මාර්ගය ලැයිස්තුගත කර නොමැති නම් මාර්ග තොරතුරු අංශය බලන්න හෝ අධිකාරිය අමතන්න.','en');
