INSERT INTO faqs(intent,question,answer,language) VALUES('feedback','How do I give feedback?','After a chat session, select a satisfaction icon and optionally enter a short note. Your feedback is saved for authorized staff. / Chat එක අවසානයේ තෘප්තිමත්භාවයේ icon එකක් තෝරා අවශ්‍ය නම් කෙටි සටහනක් දමන්න. Feedback එක බලන්න බලය ඇති නිලධාරීන්ට හැක.','en');
