INSERT INTO faqs(intent,question,answer,language) VALUES('token','Where is the token application?','Open the Token section, complete the required passenger details and submit the form. A token can then be downloaded. / Token අංශය විවෘත කර අවශ්‍ය මගී විස්තර පුරවා යවන්න. ඉන්පසු Token එක download කළ හැක.','en');
