INSERT INTO faqs(intent,question,answer,language) VALUES('roles','What are the user roles?','The system supports Passenger, Data Entry, Admin and Super Admin roles. Access is restricted by role and least-privilege rules. / පද්ධතිය Passenger, Data Entry, Admin සහ Super Admin roles සඳහා සහාය දක්වයි. Role අනුව access සීමා කර ඇත.','en');
INSERT INTO faqs(intent,question,answer,language) VALUES('roles','Who can access the administration area?','The system supports Passenger, Data Entry, Admin and Super Admin roles. Access is restricted by role and least-privilege rules. / පද්ධතිය Passenger, Data Entry, Admin සහ Super Admin roles සඳහා සහාය දක්වයි. Role අනුව access සීමා කර ඇත.','en');
