INSERT INTO faqs(intent,question,answer,language) VALUES('chatbot','What can the Assistant do?','The Assistant can answer approved transport FAQs, guide you to services and documents, and collect a satisfaction rating after the chat. / Assistant එකට අනුමත ප්‍රවාහන FAQs වලට පිළිතුරු දෙන්න, services/documents වෙත මඟ පෙන්වන්න සහ chat අවසානයේ satisfaction feedback ගන්න පුළුවන්.','en');
