INSERT INTO faqs(intent,question,answer,language) VALUES('chatbot_limits','Can the chatbot make official decisions?','The Assistant provides information from approved content; it does not replace an authorized officer or emergency service. / Assistant එක අනුමත content මත තොරතුරු ලබා දෙයි; එය නිලධාරියෙකු හෝ හදිසි සේවාවක් වෙනුවට නොවේ.','en');
